{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Rapamycin, a structurally related macrolide immunosuppressant sharing the pipecolate/hemiketal core, was measured at high levels in mouse brain after intraperitoneal administration, demonstrating that this scaffold class can achieve meaningful CNS exposure despite high molecular weight and polar surface area.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Preclinical studies in several species show that rapamycin crosses the blood-brain barrier, as measured by CSF and brain levels or inhibition of brain mTORC1 signaling, supporting transferable CNS access for the query's macrolide immunosuppressant class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Patupilone, a macrocyclic natural product, demonstrated CNS penetration in rats and mice with brain concentrations significantly greater than other tissues, supporting that large macrocycles can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Clarithromycin, a macrolide antibiotic, achieved 34% CSF penetration in rabbits with meningitis, demonstrating that macrolide scaffolds can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Temsirolimus, a rapamycin prodrug, was detected in CSF in only one of nine patients, indicating poor CNS penetration for that particular analog; however, this is a prodrug with different disposition and lower structural transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "One rapamycin study reported poor BBB traversal and no brain recombination, indicating that CNS exposure of this scaffold can be limited in certain experimental contexts.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Tacrolimus is predicted to have meaningful CNS access. Although passive physicochemical properties are unfavorable, direct evidence from structurally related macrolide immunosuppressants (rapamycin) and other macrocycles (patupilone, clarithromycin) shows that this scaffold class can cross the BBB and achieve pharmacologically relevant brain/CSF exposure. The contradictory temsirolimus and one rapamycin record reflect context- or prodrug-specific limitations and do not override the class-level CNS penetration.",
  "evidence_gaps": [
    "No direct tacrolimus brain or CSF measurement is included in the provided evidence set.",
    "Rapamycin evidence is mixed, with one record reporting poor BBB traversal.",
    "Efflux transporter contribution for tacrolimus is not directly quantified in the provided records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

